import os
from cutlass import Float16, Float32, Int32, Int64, cute
from fi_cute import fi_open, fi_b, fi_e, fi_close

EV_MOE = Int32(13)
ARCH = os.environ["WEAVEPROFILER_ARCH"]  # sm_90, sm_100a, or sm_103a
BACKEND = "cutedsl_nv"
GRAN = 0  # 0=warp lane 0; 1=linear CTA thread 0
META = {"arch": ARCH, "backend": BACKEND, "gran": "warp" if GRAN == 0 else "cta"}

@cute.jit
def pack_record(tag: Int32, aux: Int32) -> Int64:
    return (Int64(aux) << 32) | (Int64(tag) & Int64(0xFFFFFFFF))

@cute.jit
def moe_segment(records, overflow, expert, mma_atom, accumulator, x, weight0, weight1):
    ctx = fi_open(records, overflow, EV_MOE, Int32(8), fi_level=2, fi_gran=GRAN)
    aux = expert
    ctx = fi_b(ctx, EV_MOE, aux)
    if expert == Int32(0):
        cute.gemm(mma_atom, accumulator, x, weight0, accumulator)
    else:
        cute.gemm(mma_atom, accumulator, x, weight1, accumulator)
    ctx = fi_e(ctx, EV_MOE, aux)
    ctx = fi_close(ctx)
    return ctx, pack_record(EV_MOE, aux), META

