@cute.jit
def pack_record(tag: Int32, aux: Int32) -> Int64:
    return (Int64(aux) << 32) | (Int64(tag) & Int64(0xFFFFFFFF))

@cute.jit
def persistent_segment(records, overflow, lock_ptr, tidx, grid_sync, mma_atom, accumulator, a, b):
    ctx = fi_open(records, overflow, EV_MEGAKERNEL, Int32(8), fi_level=2, fi_gran=GRAN)
    aux = Int32(0)
    ctx = fi_b(ctx, EV_MEGAKERNEL, aux)
    for boundary in range(2):
        cute.gemm(mma_atom, accumulator, a, b, accumulator)
        grid_sync(lock_ptr, tidx, boundary)
    ctx = fi_e(ctx, EV_MEGAKERNEL, aux)
    ctx = fi_close(ctx)
    return ctx, pack_record(EV_MEGAKERNEL, aux), META

